import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"SVG-Line – Verbindungslinien zeichnen und animieren","description":"","frontmatter":{"title":"SVG-Line – Verbindungslinien zeichnen und animieren"},"headers":[],"relativePath":"projects/grafik-visual-studio/svg-line.md","filePath":"projects/grafik-visual-studio/svg-line.md","lastUpdated":1792861636000}'),s={name:"projects/grafik-visual-studio/svg-line.md"};function a(d,e,o,u,l,g){return t(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="svg-line" tabindex="-1">SVG-Line <a class="header-anchor" href="#svg-line" aria-label="Permalink to &quot;SVG-Line&quot;">​</a></h1><h2 id="anderungen-bis-studio-0-1-285" tabindex="-1">Änderungen bis Studio 0.1.285 <a class="header-anchor" href="#anderungen-bis-studio-0-1-285" aria-label="Permalink to &quot;Änderungen bis Studio 0.1.285&quot;">​</a></h2><ul><li><strong>Vertikale Startposition</strong> unter <strong>Linie</strong> gilt für SVG-Line und Wert-Verbindung. Ohne Haken startet eine freie Linie horizontal. Bei automatisch rechtwinkligem Pfad läuft eine vertikale Linie zuerst senkrecht und biegt auf Zielhöhe nach rechts oder links ab. Auch angedockte Linien unterstützen diese Pfadführung; manuelle Zwischenpunkte behalten Vorrang.</li><li>Punktbewegungen beginnen erst nach <strong>6 Pixeln Mausbewegung</strong>. Einzelne Griffe lösen keinen Gruppen-Drag aus und springen nicht zur Mausposition. Der jeweils andere Anschluss bleibt gebunden. <strong>Strg + Ziehen</strong> löst gezielt einen angedockten Endpunkt; <strong>Alt + Ziehen auf der Linie</strong> verschiebt eine angedockte Linie als Ganzes und löst beide Anschlüsse.</li><li>Ein expliziter <strong>Z-Index −100 oder kleiner</strong> blendet eine SVG-Line nur in der Runtime aus. Sie bleibt im Editor bearbeitbar und überträgt weiterhin Werte, etwa von Number zu Math. Das ist unabhängig von ihrer Zeichenreihenfolge im Editor.</li><li>Ab <strong>0.1.282</strong> liefert ein aktiver Gauge/Poti- oder Linear-Ausgang direkt Tempo und Richtung der angeschlossenen SVG-Line, ohne zusätzliche Zahlen-Entität. Nutze <strong>Poti / SVG LineBox-Teiler (bei Übergabe)</strong>: Wert 10 / Teiler 10 = 1 Zyklus/s; Wert 20 / Teiler 10 = 2 Zyklen/s. Null stoppt die Animation, negative Werte kehren sie um. Bei Teiler 1 erreichen Beträge ab 20 die Höchstgeschwindigkeit von 20 Zyklen/s. Für wertabhängiges Tempo die automatische Poti-/LineBox-Teileranpassung ausschalten; eingeschaltet hält sie bewusst die Zielgeschwindigkeit konstant. Wert-Verbindungen selbst haben keine Animation.</li></ul><p>Den Aufbau und die animierte Runtime-Demo findest du in der <a href="./bildergalerie">Galerie</a>.</p><p>Ab Studio 0.1.136 gibt es eine <strong>automatische Teileranpassung</strong> für Zahlen-Entitäten und LineBox-Ausgänge. Sie hält die Animation bei wechselnden Leistungen auf einer einstellbaren Geschwindigkeit. Die Einrichtung und Berechnung sind unten unter <strong>Automatische Teileranpassung: wie und warum</strong> erklärt.</p><p><strong>SVG-Line</strong> findest du unter <strong>HA Grafik – Spezial</strong>. Das Widget verbindet andere Widgets optisch, führt Linien über Ecken und kann einen Wertefluss animieren. Eine Linie kann an Widget-Andockpunkten, an einem ausdrücklich aktivierten Sammelpunkt einer anderen SVG-Line oder an freien Koordinaten beginnen und enden. Sie ist selbst keine Home-Assistant-Entität; eine optionale Entität steuert ihre Animation.</p><h2 id="verbindung-und-andockpunkte" tabindex="-1">Verbindung und Andockpunkte <a class="header-anchor" href="#verbindung-und-andockpunkte" aria-label="Permalink to &quot;Verbindung und Andockpunkte&quot;">​</a></h2><ol><li>Füge SVG-Line ein. Wähle sie im Editor aus; Anfang und Ende erscheinen als ziehbare Kreise.</li><li>Aktiviere beim Zielwidget <strong>Andockpunkte</strong> und die gewünschten Positionen. Die zwölf Punkte sind bei neuen Widgets zunächst aus: links/rechts jeweils oben, Mitte und unten; oben/unten jeweils bei 1/4, Mitte und 3/4. <strong>Alle Punkte</strong> schaltet sie gemeinsam um. Mehrere Linien dürfen denselben Punkt belegen.</li><li>Ziehe einen Linienendpunkt auf einen aktiven Andockpunkt. Alternativ stelle unter <strong>Start</strong> und <strong>Ziel</strong> jeweils Widget und Andockpunkt ein. <strong>Oder aktiver Sammelpunkt</strong> wählt einen Sammelpunkt einer anderen SVG-Line; <strong>Freies X/Y</strong> positioniert ein ungebundenes Ende.</li></ol><table tabindex="0"><thead><tr><th>Bearbeitung</th><th>Wirkung</th></tr></thead><tbody><tr><td>Freien Endpunkt ziehen</td><td>Ändert Anfang oder Ende der Linie. Mit den Pfeiltasten verschiebst du einen fokussierten Punkt um 1 Pixel, mit <code>Umschalt</code> um 10 Pixel.</td></tr><tr><td>Angedockten Endpunkt mit <code>Strg</code> ziehen</td><td>Löst die Verbindung und verschiebt den Punkt. <code>Strg</code> plus Pfeiltaste funktioniert ebenfalls.</td></tr><tr><td>Zwischenpunkt ziehen</td><td>Ändert den Verlauf des manuellen Mehrpunktpfads.</td></tr><tr><td>Ganze Linie ziehen</td><td>Freie Linie direkt ziehen; angedockte Linie mit <code>Alt</code> ziehen. Verschiebt die ganze Linie und löst dabei bisherige Start-/Ziel-Andockungen.</td></tr><tr><td>Linie ohne Ziehen anklicken</td><td>Öffnet die Wahl <strong>Zwischenpunkt</strong>, <strong>Sammelpunkt</strong> oder <strong>Wert-Koppelpunkt</strong>; nach <strong>OK</strong> wird der Punkt eingefügt.</td></tr></tbody></table><h2 id="pfad-und-sammelpunkte" tabindex="-1">Pfad und Sammelpunkte <a class="header-anchor" href="#pfad-und-sammelpunkte" aria-label="Permalink to &quot;Pfad und Sammelpunkte&quot;">​</a></h2><h3 id="wert-koppelpunkt-fur-eine-freie-anzeige" tabindex="-1">Wert-Koppelpunkt für eine freie Anzeige <a class="header-anchor" href="#wert-koppelpunkt-fur-eine-freie-anzeige" aria-label="Permalink to &quot;Wert-Koppelpunkt für eine freie Anzeige&quot;">​</a></h3><p>Ab Studio <strong>0.1.275</strong> gibt es als dritten Punkttyp den <strong>Wert-Koppelpunkt</strong>. Er gibt den Wert der SVG-Linie aus, etwa den Zahlenwert ihrer Animationsentität oder den Wert ihrer angeschlossenen Quelle. Im Editor erscheint er als Oktagon; seine Farbe stellst du unter <strong>Einstellungen → Wert-Koppelpunkt</strong> ein. Er ist ein reiner Ausgang und kann nicht als Ziel einer Linie verwendet werden.</p><p>Ab <strong>0.1.281</strong> lässt sich der Wert-Koppelpunkt ausschließlich <strong>auf dem sichtbaren Linienverlauf</strong> verschieben. Beim Ziehen bleibt er auf dem nächstgelegenen Punkt der Linie, auch bei Kurven und gerundeten Ecken. Er verändert weder den Linienverlauf noch die gewählte Pfadart. Nur Zwischen- und Sammelpunkte formen den Pfad. Die abgehende Anzeigeverbindung folgt nach dem Verschieben der neuen Position. Ältere Punkte neben der Linie sowie manuell eingegebene Positionen werden auf den Pfad gesetzt.</p><ol><li>Wähle die SVG-Linie aus, klicke erneut auf die gewünschte Stelle und füge einen <strong>Wert-Koppelpunkt</strong> ein.</li><li>Platziere ein <strong>Number</strong>-Widget frei neben, über oder unter der Linie. Aktiviere unter <strong>Datenfluss</strong> seinen <strong>Eingangspunkt</strong> und wähle dessen Seite.</li><li>Füge eine Verbindung ein. Wähle unter <strong>Start → Sammel- oder Wert-Koppelpunkt</strong> den neuen Punkt oder ziehe den Anfang darauf. Verbinde das Ziel mit dem Eingang von Number.</li></ol><p>Der Punkt und die abgehende Verbindung sind in der Runtime automatisch unsichtbar; die Wertübernahme bleibt aktiv. Die ursprüngliche SVG-Linie bleibt sichtbar. <strong>String</strong> kann auf dieselbe Weise einen Textwert aus dem Datenfluss anzeigen. Über <strong>Linienpunkte</strong> lassen sich Name, Position und Punkttyp später ändern. Unbekannte Werte werden nicht durch eine erfundene Null ersetzt.</p><p>Unter <strong>Pfad und Sammelpunkte</strong> gibt es vier <strong>Pfadarten</strong>: <strong>Gerade</strong>, <strong>Automatisch rechtwinklig</strong>, <strong>Kurve</strong> und <strong>Manueller Zickzack-/Mehrpunktpfad</strong>. Der <strong>Eckenradius</strong> rundet Ecken im passenden Verlauf ab. Über <strong>Zwischenpunkte und Sammelpunkte</strong> kannst du Punkte benennen, setzen und bearbeiten. Ein per Klick eingefügter Zwischen- oder Sammelpunkt wechselt die Linie in den manuellen Mehrpunktmodus.</p><p>Ein <strong>Zwischenpunkt</strong> knickt nur den Pfad. Ein <strong>Sammelpunkt</strong> ist ein möglicher Anschluss für weitere SVG-Lines, wenn er aktiviert ist. Ziehe deren freien Endpunkt auf den sichtbaren Sammelpunkt oder wähle ihn in den Eigenschaften. Mehrere Linien können denselben Sammelpunkt nutzen. Eine bloße Kreuzung oder Berührung koppelt keine Linien. Ein deaktivierter Sammelpunkt nimmt keine neue Verbindung an.</p><h2 id="linie-und-pfeilspitzen" tabindex="-1">Linie und Pfeilspitzen <a class="header-anchor" href="#linie-und-pfeilspitzen" aria-label="Permalink to &quot;Linie und Pfeilspitzen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gruppe</th><th>Einstellmöglichkeiten</th></tr></thead><tbody><tr><td><strong>Linie</strong></td><td><strong>Grundfarbe</strong>, <strong>Animationsfarbe</strong>, <strong>Dicke</strong> (1–40 px), <strong>Deckkraft</strong>, <strong>Linienart</strong> (durchgezogen, gestrichelt, gepunktet), <strong>Strichlänge</strong>, <strong>Abstand</strong> zwischen Strichen/Punkten und <strong>Linienenden</strong> (rund, stumpf, quadratisch).</td></tr><tr><td><strong>Pfeilspitzen</strong></td><td><strong>Am Anfang</strong> und <strong>Am Ende</strong> unabhängig: keine, gefüllter Pfeil, offener Pfeil oder Kreis. <strong>Größe</strong> und <strong>Farbe</strong> gelten für die Marker. Bei umgekehrter Flussrichtung wechseln die angezeigten Marker ihre Seite.</td></tr></tbody></table><h2 id="animation-und-richtungsquelle" tabindex="-1">Animation und Richtungsquelle <a class="header-anchor" href="#animation-und-richtungsquelle" aria-label="Permalink to &quot;Animation und Richtungsquelle&quot;">​</a></h2><p>Aktiviere <strong>Animation aktivieren</strong> und wähle als <strong>Animationsart</strong> Zweifarbenfluss, laufende Striche, Puls oder Lichtpunkt. Unter <strong>Richtungsquelle</strong> ist immer genau eine Variante aktiv:</p><table tabindex="0"><thead><tr><th>Quelle</th><th>Richtung und Geschwindigkeit</th></tr></thead><tbody><tr><td><strong>Manuell</strong></td><td><strong>Richtung</strong> Anfang → Ende oder Ende → Anfang sowie <strong>Dauer</strong> von 0,2–20 Sekunden je Zyklus. Bei Verbindung mit einem Sammelpunkt richtet sich der manuelle Fluss auf diesen Punkt aus.</td></tr><tr><td><strong>Zahlen-Entität</strong></td><td>Positive Werte laufen vom Anfang zum Ende, negative umgekehrt; <code>0</code> stoppt den Fluss. Betrag ÷ <strong>Teiler</strong> (Standard <code>1</code>) ergibt Zyklen pro Sekunde, begrenzt auf 0,05–20. Beispiel: <code>1000 W ÷ 100 = 10</code> Zyklen/s.</td></tr><tr><td><strong>Bool-Entität</strong></td><td><code>on</code>/<code>true</code>/<code>1</code> läuft vorwärts, <code>off</code>/<code>false</code>/<code>0</code> rückwärts. <strong>Bool-Richtung umkehren</strong> tauscht die Zuordnung. Die eingestellte <strong>Dauer</strong> bestimmt den Takt.</td></tr></tbody></table><p>Fehlende oder ungültige Entitätszustände halten die Animation an. Die ausgewählte Entität wird im Editor und in der Runtime aktualisiert. Die <strong>SVG LineBox</strong> kann an einem als Ausgang eingerichteten Andockpunkt Vorzeichen und Betrag ihres berechneten Wertes an die Linie übergeben. Diese Übergabe hat Vorrang vor der gewählten Richtungsquelle. Die Ausgangslinie braucht weiterhin <strong>Animation aktivieren</strong>; bei <code>0</code> oder ohne gültigen Eingang steht sie still. <strong>SVG LineBox-Teiler (bei Übergabe)</strong> bestimmt dann ihren Takt, während ihre eigenen Farben und Linienart erhalten bleiben. <a href="./svg-linebox">SVG LineBox ausführlich erklärt</a>.</p><h2 id="automatische-teileranpassung-wie-und-warum" tabindex="-1">Automatische Teileranpassung: wie und warum <a class="header-anchor" href="#automatische-teileranpassung-wie-und-warum" aria-label="Permalink to &quot;Automatische Teileranpassung: wie und warum&quot;">​</a></h2><p>Bei einem festen Teiler wächst die Geschwindigkeit mit dem Eingangswert. Mit Teiler <code>100</code> ergeben beispielsweise <code>10 W</code> nur <code>0,1</code> Zyklen/s, aber <code>1500 W</code> bereits <code>15</code> Zyklen/s. Ein größerer Teiler bremst hohe Leistungen von Heizung oder Herd, macht kleine Werte jedoch sehr langsam. Ein kleinerer Teiler beschleunigt kleine Werte und kann große Werte schwer erkennbar animieren.</p><p>Die Automatik passt deshalb den Teiler bei jeder Wertänderung an die gewählte <strong>Zielgeschwindigkeit</strong> an. Sie verwendet keine festen Leistungsstufen und funktioniert auch oberhalb von 15.000. Der Zusammenhang lautet:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Automatischer Teiler = Betrag des Eingangswerts / Zielgeschwindigkeit</span></span>
<span class="line"><span>Animationsgeschwindigkeit = Betrag des Eingangswerts / automatischer Teiler</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Bei <strong>1 Zyklus/s</strong> ergeben sich folgende Werte:</p><table tabindex="0"><thead><tr><th>Eingangswert</th><th>Automatischer Teiler</th><th>Geschwindigkeit</th></tr></thead><tbody><tr><td>10</td><td>10</td><td>1 Zyklus/s</td></tr><tr><td>100</td><td>100</td><td>1 Zyklus/s</td></tr><tr><td>1500</td><td>1500</td><td>1 Zyklus/s</td></tr><tr><td>15.000</td><td>15.000</td><td>1 Zyklus/s</td></tr></tbody></table><p>So bleibt der Fluss bei kleinen und großen Leistungen ähnlich gut erkennbar. Die Geschwindigkeit zeigt bei eingeschalteter Automatik die gewählte Zielgeschwindigkeit; aus ihr lässt sich die Höhe der Leistung nicht mehr ablesen. Das Vorzeichen steuert weiterhin die Richtung. <code>0</code>, fehlende Werte und ungültige Zustände halten die Animation an.</p><h3 id="einrichten" tabindex="-1">Einrichten <a class="header-anchor" href="#einrichten" aria-label="Permalink to &quot;Einrichten&quot;">​</a></h3><ol><li>Wähle die SVG-Line und aktiviere unter <strong>Animation</strong> <strong>Animation aktivieren</strong>.</li><li>Für eine HA-Zahlenquelle wähle <strong>Richtungsquelle → Zahlen-Entität</strong>, trage die Entität ein und aktiviere <strong>Teiler automatisch anpassen (Zahlen-Entität)</strong>.</li><li>Für einen verbundenen Ausgang von <strong>SVG LineBox</strong> oder <a href="./svg-linebox-math"><strong>SVG LineBox Math</strong></a> aktiviere stattdessen <strong>Teiler automatisch anpassen (SVG LineBox)</strong>. Diese Wertübergabe hat Vorrang vor der gewählten Richtungsquelle.</li><li>Stelle die jeweils zugehörige <strong>Zielgeschwindigkeit</strong> ein. Standard ist <strong>1 Zyklus/s</strong>; erlaubt sind <strong>0,05–5 Zyklen/s</strong>. Mit <code>0,5</code> dauert ein Zyklus zwei Sekunden, mit <code>2</code> eine halbe Sekunde. Beginne mit <code>1</code> und passe den Wert anhand deiner Linienart und Strichabstände an.</li></ol><p>Beide Automatiken sind unabhängig und zunächst ausgeschaltet. Der jeweilige manuelle <strong>Teiler</strong> bleibt gespeichert; bei ausgeschalteter Automatik wird er wieder verwendet. <strong>Manuell</strong> und <strong>Bool-Entität</strong> verwenden weiterhin ihre eingestellte Dauer. Eine übernommene Hauptlinienanimation gilt weiterhin für normale Nebenlinien; ein aktiv weitergegebener LineBox-Wert bestimmt den Takt der betreffenden Ausgangslinie selbst.</p><p>Zyklen pro Sekunde sind die Wiederholungen der Animation, keine Pixelgeschwindigkeit. Linienart, Animationsart und Strichabstände beeinflussen das sichtbare Ergebnis. Die Automatik liefert einen stabilen Takt; die passende Zielgeschwindigkeit lässt sich deshalb je Linie einstellen.</p><h2 id="hauptlinie-kreuzungen-und-ebenen" tabindex="-1">Hauptlinie, Kreuzungen und Ebenen <a class="header-anchor" href="#hauptlinie-kreuzungen-und-ebenen" aria-label="Permalink to &quot;Hauptlinie, Kreuzungen und Ebenen&quot;">​</a></h2><p>Mit <strong>Hauptlinie / Flussgruppe</strong> ordnest du eine Linie einer anderen zu. <strong>Animationstakt der Hauptlinie übernehmen (eigene Farben behalten)</strong> übernimmt Takt und Animationsart, während die Nebenlinie bei laufendem Fluss ihre eigene Farbe behält. <strong>Synchronisierung</strong> bietet <strong>Gleicher Takt</strong> und <strong>Am Sammelpunkt synchron ankommen</strong>. Bei direkter Kopplung an einen Sammelpunkt einer nicht animierten Hauptlinie stoppt die Nebenlinie ebenfalls und zeigt deren Grundfarbe einschließlich der Pfeilspitzen. Nach dem Lösen gelten wieder die gespeicherten eigenen Einstellungen.</p><p>Unter <strong>Kreuzung und z-index</strong> stehen <strong>Überlagerung</strong>, <strong>Lücke</strong> und <strong>Brücke / Bogen</strong> sowie <strong>Automatisch</strong>, <strong>Darüber</strong>, <strong>Darunter</strong> oder <strong>Manuell</strong> für die Stapelung zur Verfügung. Ein höherer z-index liegt sichtbar vor einem niedrigeren. <strong>Klicks durchlassen</strong> beeinflusst die Interaktion in der Runtime. Kreuzungsdarstellung und z-index verbinden Linien nicht; dazu brauchst du einen Sammelpunkt oder die <a href="./svg-linebox">SVG LineBox</a>.</p><p>SVG-Line ist noch experimentell; insbesondere Kreuzungseffekte und synchronisierte Animation können sich je nach Pfad und Browser unterscheiden.</p>`,38)])])}const k=n(s,[["render",a]]);export{c as __pageData,k as default};
